CREATE TABLE Applications(applicationId nvarchar(36) PRIMARY KEY,name nvarchar(200) NOT NULL,description nvarchar(max) NULL,createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),updatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Modules(moduleId nvarchar(36) PRIMARY KEY,applicationId nvarchar(36) NOT NULL,name nvarchar(200) NOT NULL,description nvarchar(max) NULL,CONSTRAINT FK_Modules_Applications FOREIGN KEY(applicationId) REFERENCES Applications(applicationId));
CREATE TABLE Features(featureId nvarchar(36) PRIMARY KEY,moduleId nvarchar(36) NOT NULL,name nvarchar(200) NOT NULL,description nvarchar(max) NULL,CONSTRAINT FK_Features_Modules FOREIGN KEY(moduleId) REFERENCES Modules(moduleId));
CREATE TABLE Sprints(sprintId nvarchar(36) PRIMARY KEY,name nvarchar(200) NOT NULL,startDate date NULL,endDate date NULL,createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),updatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Releases(releaseId nvarchar(36) PRIMARY KEY,name nvarchar(200) NOT NULL,targetDate date NULL,description nvarchar(max) NULL,createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),updatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE UserStories(userStoryId nvarchar(36) PRIMARY KEY,title nvarchar(300) NOT NULL,description nvarchar(max) NOT NULL,applicationId nvarchar(36) NOT NULL,moduleId nvarchar(36) NULL,featureId nvarchar(36) NOT NULL,storyPoints decimal(10,2) NOT NULL CHECK(storyPoints>=0),priority nvarchar(20) NOT NULL,status nvarchar(30) NOT NULL,sprintId nvarchar(36) NULL,releaseId nvarchar(36) NULL,assigneeId nvarchar(36) NULL,businessOwnerId nvarchar(36) NULL,acceptanceCriteria nvarchar(max) NULL,dependencies nvarchar(max) NULL,createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),updatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),createdById nvarchar(200) NOT NULL,updatedById nvarchar(200) NOT NULL,deletedAt datetime2 NULL,deletedById nvarchar(200) NULL);
CREATE TABLE StatusHistory(historyId nvarchar(36) PRIMARY KEY,userStoryId nvarchar(36) NOT NULL,previousStatus nvarchar(30) NULL,newStatus nvarchar(30) NOT NULL,actorId nvarchar(200) NOT NULL,occurredAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_History_Story FOREIGN KEY(userStoryId) REFERENCES UserStories(userStoryId));
CREATE TABLE AuditTrail(auditId nvarchar(36) PRIMARY KEY,userStoryId nvarchar(36) NULL,entityType nvarchar(100) NOT NULL,action nvarchar(100) NOT NULL,actorId nvarchar(200) NOT NULL,occurredAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),changeSummary nvarchar(max) NOT NULL,CONSTRAINT CK_Audit_No_Bodies CHECK(changeSummary NOT LIKE '%password%' AND changeSummary NOT LIKE '%token%'));
CREATE INDEX IX_UserStories_Active ON UserStories(deletedAt,status,applicationId,sprintId);
